import fs from 'node:fs';
import {contentVersion} from './content-version.mjs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {trips,regions} from '../data/trips.mjs';
import {faithPages,faithFeature} from './faith-pages.mjs';
import {heritagePages,heritageFeature,signatureJourneys} from './heritage-pages.mjs';
import {heritageGuides} from './heritage-guides.mjs';
import {servicePages} from './service-pages.mjs';
import {packageDetails,planningCalendar} from './package-details.mjs';
import {policyContent} from './policy-content.mjs';
import {dayPlanning,journeyExtensions,sidebarDates} from './journey-details.mjs';
import {tripPresentation} from './trip-presentation.mjs';
import {departureCards} from './departure-cards.mjs';
import {readJson,editablePage,validatePlain} from './content.mjs';
import {versionAssets} from './version-assets.mjs';
process.chdir(path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'));
const config=JSON.parse(fs.readFileSync('site.config.json','utf8'));
const homeContent=readJson('content/home.json');
const uploadManifest=readJson('data/upload-manifest.json');
const uploadAlts=new Map([...trips,...regions].filter(t=>t.cover).map(t=>[t.cover.replace(/^\//,''),t.coverAlt||t.name+' landscape']));
trips.forEach(t=>(t.gallery||[]).forEach(src=>uploadAlts.set(src.replace(/^\//,''),t.name+' destination photograph')));
if(homeContent.heroImage)uploadAlts.set(homeContent.heroImage.replace(/^\//,''),homeContent.heroAlt||'Mountain landscape');
let policies;
const out=(f,c)=>fs.writeFileSync(f,c);
const esc=(s='')=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
policies=policyContent(esc);
const money=n=>`₹${n.toLocaleString('en-IN')}`;
const photos={'dal-lake':[1600,1071,'Shikaras along Dal Lake in Srinagar'],valley:[1000,1364,'Green mountain valley and river; illustrative regional photograph'],'mountain-road':[1000,1344,'Motorcycle on a mountain road; illustrative riding photograph'],pangong:[1280,848,'Blue water and mountains at Pangong Tso, Ladakh'],patnitop:[1280,720,'Deodar trees and clouds at Patnitop, Jammu']};
const photoDimensions=JSON.parse(fs.readFileSync('data/photo-dimensions.json','utf8').replace(/^\uFEFF/,''));
const photoCredits=JSON.parse(fs.readFileSync('data/photo-credits.json','utf8').replace(/^\uFEFF/,''));
const photoAlts={vishansar:'Vishansar alpine lake in Kashmir',tulian:'Tulian Lake near Pahalgam',warwan:'Landscape in Warwan Valley',autumn:'Autumn chinar foliage in Kashmir',gurez:'Wooden cabin and pine-covered slopes in Gurez Valley',gulmarg:'Snow-covered mountains and pines in Gulmarg',bhaderwah:'Bhaderwah town and surrounding hills in Jammu',nubra:'Nubra Valley landscape near Diskit, Ladakh',dal:'View from a shikara on Dal Lake, Srinagar','great-lakes':'Alpine meadow on the Kashmir Great Lakes route',khardung:'Mountain road towards Khardung La, Ladakh',katra:'Shri Mata Vaishno Devi Bhawan above Katra','gurez-landscape':'Pine-covered landscape in Gurez Valley, Kashmir'};
Object.assign(photoAlts,{charar:"Mosque and town setting at Charar-e-Sharief",'kheer-bhawani':"Kheer Bhawani temple surroundings at Tulmulla",'chatti-padshahi':"Gurdwara Chatti Padshahi in Srinagar beneath the mountain slopes",'all-saints':"All Saints Church in Srinagar"});
Object.entries(photoDimensions).forEach(([key,p])=>photos[key]=[p.width,p.height,photoAlts[key]||photoCredits.find(c=>c.key===key)?.title.replace(/^File:/,'').replace(/\.[a-z]+$/i,'')||key]);
function img(k,cls='',eager=false,altOverride=''){if(k?.startsWith('/assets/'))k=k.slice(1);if(uploadManifest[k]){const p=uploadManifest[k];return `<img class="${cls}" src="${p.src}" srcset="${p.variants.map(v=>v.src+' '+v.width+'w').join(', ')}" sizes="${eager?'100vw':'(max-width: 600px) 100vw, 50vw'}" width="${p.width}" height="${p.height}" alt="${esc(altOverride||uploadAlts.get(k)||'Destination photograph')}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;} k=({'dal-lake':'dal',valley:'gurez-landscape','mountain-road':'khardung'})[k]||k;const [w,h,alt]=photos[k];return `<img class="${cls}" src="assets/${k}-${w}.jpg" srcset="assets/${k}-640.jpg 640w, assets/${k}-${w}.jpg ${w}w" sizes="${eager?'100vw':'(max-width: 600px) 100vw, (max-width: 900px) 50vw, 33vw'}" width="${w}" height="${h}" alt="${esc(altOverride||alt)}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;}
const button=(url,label,style='')=>`<a class="button ${style}" href="${url}">${label}<span aria-hidden="true">↗</span></a>`;
const wa=`https://wa.me/${config.whatsapp}`;
const brand=`<a class="brand" href="index.html" aria-label="The Holiday Host home"><img src="assets/mark.svg" width="42" height="42" alt=""><span><strong>${esc(config.name)}</strong><small>Kashmir · Ladakh · Jammu</small></span></a>`;
const footer=`<footer class="footer"><div class="wrap"><div class="footer-grid"><div>${brand}<p>Three remarkable regions.<br>A little more time to discover them.</p><a href="${wa}">Chat on WhatsApp ↗</a></div><div><h3>Destinations</h3><ul>${regions.map(r=>`<li><a href="${r.slug}.html">${r.name}</a></li>`).join('')}<li><a href="packages.html">All journeys</a></li><li><a href="departures.html">Travel dates</a></li><li><a href="experiences.html">Local experiences</a></li><li><a href="kashmir-heritage.html">Kashmir heritage & crafts</a><a href="faith-journeys.html">Faith journeys</a></li><li><a href="transport.html">Transport</a></li></ul></div><div><h3>Get to know us</h3><ul><li><a href="about.html">Our story</a></li><li><a href="blog.html">Field notes</a></li><li><a href="reviews.html">Guest stories</a></li><li><a href="faq.html">FAQs</a></li><li><a href="contact.html">Plan a trip</a></li></ul></div><div><h3>Let’s talk</h3><ul><li><a href="tel:${config.phone}">${esc(config.phone)}</a></li><li><a href="mailto:${config.email}">${config.email}</a></li><li>${esc(config.location)}</li></ul><p>Opening hours to be confirmed.</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} The Holiday Host</span><div><a href="terms.html">Terms</a><a href="privacy.html">Privacy</a><a href="cancellation.html">Cancellation & refunds</a><a href="credits.html">Photo credits</a></div></div></div></footer><a class="floating-contact" href="${wa}" aria-label="Chat with The Holiday Host on WhatsApp"><span aria-hidden="true">◉</span> WhatsApp us</a>`;
const stylePhotos={Group:'gurez','Women-only':'warwan',Trek:'vishansar',Private:'dal',Motorcycle:'khardung',Pilgrimage:'katra'};
const reviewsData=JSON.parse(fs.readFileSync('data/reviews.json','utf8'));
const reviewsBlock=()=>`<section class="section reviews-section"><div class="wrap"><div class="section-head centered"><div><span class="eyebrow">Google customer feedback</span><h2>Good journeys.<br><em>Real experiences.</em></h2></div><p>Selected summaries of public reviews. Read each customer’s own words on Google.</p></div><div class="google-rating"><span class="google-word">Google</span><strong>${reviewsData.aggregate.rating.toFixed(1)}<small> / 5</small></strong><span>from ${reviewsData.aggregate.count} reviews</span><a href="${esc(reviewsData.aggregate.source)}">View all Google reviews ↗</a><small>Observed 3 November 2026 · ratings may change</small></div><div class="review-grid">${reviewsData.reviews.map(r=>'<article class="review-card"><span class="review-kind">Review summary</span><p>'+esc(r.text)+'</p><div class="review-author"><span aria-hidden="true">'+esc(r.name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase())+'</span><strong>'+esc(r.name)+'</strong></div><a href="'+esc(r.source)+'">Read the original review ↗</a></article>').join('')}</div></div></section>`;
const pages=[];
function prepareForms(body){return body.replace(/(<form class="enquiry-form"[^>]*>)/g,'$1<fieldset data-enquiry-fields disabled><legend class="sr-only">Your trip enquiry</legend>').replaceAll('</section></form>','</section></fieldset></form>').replace('<img id="photo-full" width="1280" height="848" alt="">','<img id="photo-full" width="1280" height="848" alt="">');}
function page(file,title,description,body,noindex=false){({title,description,body}=editablePage(file,title,description,body,esc,img));pages.push(file);const canonical=`${config.url}/${file==='index.html'?'':file}`;out(file,`<!doctype html>
<html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#173f35"><title>${esc(title)} | The Holiday Host</title><meta name="description" content="${esc(description)}">${noindex?'<meta name="robots" content="noindex,follow">':''}<link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="The Holiday Host"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${config.url}/assets/pangong-1280.jpg"><meta property="og:image:alt" content="Pangong Tso, Ladakh"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="assets/site.css"><script src="assets/contact-config.js" defer></script><script src="assets/site.js" defer></script><script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'TravelAgency',name:config.name,url:config.url,telephone:config.phone,email:config.email,address:config.location,areaServed:['Kashmir','Ladakh','Jammu']})}</script></head><body class="${file==='index.html'?'home-page':''}"><a class="skip" href="#main">Skip to content</a><div class="topline">Kashmir. Ladakh. Jammu. <span>Find your own way north.</span></div><header class="header"><nav class="nav wrap" aria-label="Main navigation">${brand}<button class="menu" type="button" aria-expanded="true" aria-controls="navigation">Menu ☰</button><div class="navlinks" id="navigation"><details class="nav-drop"><summary>Destinations</summary><div>${regions.map(r=>`<a href="${r.slug}.html">${r.name}</a>`).join('')}<a href="destinations.html">All destinations</a><a href="experiences.html">Local experiences</a><a href="kashmir-heritage.html">Kashmir heritage & crafts</a><a href="faith-journeys.html">Faith journeys</a><a href="transport.html">Transport enquiries</a></div></details><details class="nav-drop"><summary>Trips</summary><div><a href="packages.html">All trips & tours</a><a href="motorcycle-tours.html">Motorcycle journeys</a>${['Group','Women-only','Trek','Day trip','Private','Motorcycle','Pilgrimage'].map(type=>`<a href="packages.html?type=${encodeURIComponent(type)}">${type}</a>`).join('')}</div></details><a href="departures.html">Departures</a><a href="blog.html">Stories</a><a href="about.html">About us</a>${button('contact.html','Plan my trip')}</div></nav></header><main id="main">${prepareForms(body)}</main>${footer}<dialog id="photo-dialog" aria-labelledby="photo-caption"><button type="button" class="dialog-close" aria-label="Close photo">×</button><img id="photo-full" width="1280" height="848" alt=""><p id="photo-caption"></p></dialog></body></html>\n`);}
const head=(label,title,description)=>`<section class="pagehead"><div class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><span>${label}</span></nav><span class="eyebrow">${label}</span><h1>${title}</h1><p>${description}</p></div></section>`;
const cta=`<section class="cta"><div class="wrap"><div><span class="eyebrow">A place in mind? A feeling to follow?</span><h2>Let’s make it<br><em>your kind of journey.</em></h2><p>Tell us your dates, your people, and what you’d love to experience.</p></div><div class="cta-actions">${button('contact.html','Plan a custom trip','cream')}${button(wa,'Talk on WhatsApp','glass')}</div></div></section>`;
const allPhotoCredits=()=>photoCredits.map(p=>'<article class="photo-credit"><h2>'+esc(p.title.replace('File:',''))+'</h2><p>Photo by '+esc(p.author)+'. <a href="'+esc(p.source)+'">Wikimedia Commons source</a> · <a href="'+esc(p.licenseUrl)+'">'+esc(p.license)+'</a>. Resized and recompressed; responsive crops vary. No endorsement is implied. Adapted files are offered under the source licence.</p><p>'+photoDimensions[p.key].variants.map(v=>'<a href="'+v.src+'">'+v.width+'px version</a>').join(' · ')+'</p></article>').join('');
const pricingNote=`<p class="pricing-note">ⓘ Guide prices for planning, subject to availability and supplier confirmation. Your written quote confirms the total, taxes, sharing basis, and exact inclusions.</p>`;
const price=t=>t.price?`<span class="price">${money(t.price)}</span><small>guide / person</small>`:'<span class="price request-price">Price on request</span><small>tailored to your group</small>';
function cards(list=trips){return `<div class="trip-grid">${list.map(t=>`<article class="trip-card" data-trip-card data-region="${t.region}" data-type="${t.type}" data-days="${t.days}" data-price="${t.price||999999}" data-search="${esc([t.name,t.region,t.type,t.route,...t.tags||[],...t.highlights].join(' ').toLowerCase())}"><a class="card-image" href="${t.slug}.html" aria-label="Explore ${esc(t.name)}">${img(t.cover||t.image)}<span class="card-tag">${t.type==='Women-only'?'Women-only proposal':t.type+' journey'}</span><span class="difficulty">${t.difficulty}</span></a><div class="card-body"><div class="card-meta"><span>${t.region}</span><span>${t.days} days · ${t.nights} nights</span></div><h3><a href="${t.slug}.html">${t.name}</a></h3><p>${t.description}</p><div class="card-highlights">${t.highlights.slice(0,2).map(h=>`<span>✓ ${h}</span>`).join('')}</div><div class="card-bottom"><div>${price(t)}</div><a class="circle-link" href="${t.slug}.html" aria-label="View ${esc(t.name)}">↗</a></div><span class="card-status">${t.price?'Guide price · ':''}Availability on request</span></div></article>`).join('')}</div>`;}
const regionCards=()=>`<div class="region-grid">${regions.map((r,i)=>`<a class="region-card" href="${r.slug}.html">${img(r.cover||r.image)}<div><span class="eyebrow">0${i+1} / ${trips.filter(t=>t.region.includes(r.name)).length} journeys to explore</span><h3>${r.name}</h3><p>${r.line}</p><span class="round-arrow" aria-hidden="true">↗</span></div></a>`).join('')}</div>`;
const faqs=[['How do I book a trip?','Choose a journey, request your preferred dates, and send an enquiry by WhatsApp or email. The team must confirm availability, the total price, and final terms in writing before any booking or payment.'],['Are these guide prices or confirmed offers?','They are owner-authorised guide prices for planning, not live inventory or a promise of availability. The final quote must confirm dates, occupancy, transport, meals, activities, taxes, and supplements.'],['What is included?','Each trip has a proposed inclusion list and an exclusion list. Most overnight proposals cover stays, breakfast and dinner, and agreed route transport. Flights, insurance, lunches, and optional activities are generally separate. Only your accepted quote determines the actual package.'],['Can I join as a solo traveller?','You can request a place on a proposed group journey. Room sharing, group size, departure viability, hosting, and any single supplement must be confirmed first. Women-only proposals also depend on confirmed staffing and a viable departure.'],['Do you have confirmed departures?','No fixed departures or seat counts have been supplied yet. Request a future date and the team will check whether a group departure or a private alternative can be arranged.'],['Can I customise a trip?','The enquiry flow supports custom itineraries and preferences. Request a revised proposal for different stays, more rest days, private transport, or a combined regional route.'],['What are the cancellation terms?','Final business-approved payment, cancellation, and refund conditions are still required. The policy pages identify the missing terms. Agree the final conditions before paying.'],['Is WhatsApp available?','Yes. The owner supplied +91 99062 69900 as the business WhatsApp number. Review your enquiry, open WhatsApp, and press Send yourself.']];
const faqList=(items=faqs)=>items.map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('');
function gallery(keys=['gurez-village','kokernag','verinag']){keys=[...new Set(keys.map(k=>({'dal-lake':'dal',valley:'gurez-landscape','mountain-road':'khardung'})[k]||k).map(k=>k.replace(/^\//,'')))];return '<div class="gallery">'+keys.map(k=>{const source=uploadManifest[k]?.src||'assets/'+k+'-'+photos[k]?.[0]+'.jpg';const caption=uploadAlts.get(k)||photos[k]?.[2]||'Destination photograph';return '<button type="button" class="gallery-item" data-photo="'+source+'" data-caption="'+esc(caption)+'">'+img(k)+'<span>View photograph ↗</span></button>';}).join('')+'</div><p class="small muted">Destination inspiration, not photographs of a confirmed Holiday Host departure. <a href="credits.html">Photo credits & licences</a>.</p>';}
page('index.html','Kashmir, Ladakh & Jammu journeys','Discover proposed group trips, treks, and private Kashmir, Ladakh, and Jammu journeys. Explore guide prices and enquire on WhatsApp.',`<section class="hero"><div class="hero-photo">${img(homeContent.heroImage||'gurez-landscape','',true)}<span class="photo-label">${esc(homeContent.heroCaption)}</span></div><div class="wrap hero-content"><span class="eyebrow">Kashmir · Ladakh · Jammu</span><h1>${esc(homeContent.heroTitle)}<br><em>${esc(homeContent.heroEmphasis)}</em></h1><p>${esc(homeContent.heroDescription)}</p><div class="actions">${button('packages.html','Find your next journey')}${button('destinations.html','Explore destinations','outline')}</div><div class="hero-footnote"><span aria-hidden="true">✳</span><p>Closer to the place.<br><strong>More room to be yourself.</strong></p></div></div></section><section class="search-section"><div class="wrap"><form class="searchbar" action="packages.html" role="search"><span aria-hidden="true">⌕</span><label class="sr-only" for="home-search">Search trips and destinations</label><input id="home-search" name="q" type="search" placeholder="Where would you like to go?" maxlength="100"><button class="button" type="submit">Find my trip →</button></form><div class="popular"><span>Follow your curiosity:</span>${[['Kashmir','region=Kashmir'],['Ladakh','region=Ladakh'],['Jammu','region=Jammu'],['Women-only','type=Women-only'],['Treks','type=Trek']].map(([n,q])=>`<a href="packages.html?${q}">${n} ↗</a>`).join('')}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">The places we dream of</span><h2>North is a feeling.</h2></div><p>Pick a landscape that calls to you.<br>We’ll help you find your pace.</p></div>${regionCards()}</div></section>${departureCards(trips,{img,price,slugs:homeContent.departureSlugs})}<section class="section tint"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Explore the trip collection</span><h2>Where will you<br><em>go next?</em></h2></div><a class="text-link" href="packages.html">Explore all ${trips.length} journeys ↗</a></div>${cards(homeContent.featuredSlugs.map(slug=>trips.find(t=>t.slug===slug)).filter(Boolean))}${pricingNote}</div></section>${reviewsBlock()}<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">A glimpse of the journey</span><h2>The kind of places<br>you carry home.</h2></div><p>More sky. More space. More reasons to put the phone away for a while.</p></div>${gallery()}</div></section><section class="section tint"><div class="wrap split"><div><span class="eyebrow">The Holiday Host way</span><h2>Let’s get the<br><em>little things right.</em></h2><p class="muted">Know what’s planned, what’s included, and what still needs confirming.</p><a class="text-link" href="about.html">Get to know us ↗</a></div><ol class="principles">${[['Start with a conversation','Your interests and pace shape the proposal.'],['Put the details in writing','Stays, transport, activities, costs, and exclusions.'],['Keep room for the mountains','Weather, access, and wellbeing guide the final route.']].map(([h,p],i)=>`<li><span>0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></li>`).join('')}</ol></div></section><section class="section custom-planner"><div class="wrap split"><div><span class="eyebrow">Your dates. Your kind of travel.</span><h2>Let’s plan<br><em>something special.</em></h2><p>Tell us a little about your trip. Review your request and send it straight to our team.</p><ul class="tick-list"><li>Personal itinerary discussion</li><li>Clear inclusions and exclusions</li><li>Direct WhatsApp enquiry</li></ul></div><div>${enquiryForm('home-enquiry')}</div></div></section><section class="section"><div class="wrap split"><div><span class="eyebrow">Before you go</span><h2>A little clarity.<br>A better journey.</h2><a href="faq.html" class="text-link">All your questions ↗</a></div><div>${faqList(faqs.slice(0,4))}</div></div></section>${signatureJourneys({esc,button})}${heritageFeature({img,esc,button})}<section class="section"><div class="wrap">${faithFeature({button})}</div></section>${cta}`);
const filters=`<form id="trip-filters" class="filters" role="search"><div class="filter-search"><label for="trip-search">Search journeys</label><input id="trip-search" name="q" type="search" placeholder="Try Gurez, family, trekking…" maxlength="100"></div><div><label for="filter-region">Destination</label><select id="filter-region" name="region"><option value="">All destinations</option>${regions.map(r=>`<option>${r.name}</option>`).join('')}</select></div><div><label for="filter-type">Travel style</label><select id="filter-type" name="type"><option value="">All styles</option>${[...new Set(trips.map(t=>t.type))].map(v=>`<option>${v}</option>`).join('')}</select></div><div><label for="filter-duration">Duration</label><select id="filter-duration" name="duration"><option value="">Any length</option><option value="short">1–4 days</option><option value="week">5–7 days</option><option value="long">8+ days</option></select></div><div><label for="filter-sort">Sort by</label><select id="filter-sort" name="sort"><option value="recommended">Recommended</option><option value="price-low">Guide price: low to high</option><option value="price-high">Guide price: high to low</option><option value="duration">Duration</option></select></div><button type="reset" class="reset">Clear filters</button></form>`;
page('packages.html','Find your next journey','Search proposed Kashmir, Ladakh, and Jammu journeys by region, travel style, duration, and guide price.',`${head('Find a trip','There’s a journey<br>with your name on it.','Group adventures, private escapes, treks, and quieter corners. Explore the possibilities, then make them your own.')}<section class="section catalogue"><div class="wrap">${filters}<div class="results-bar"><p id="results-count" role="status">${trips.length} journey proposals to explore</p><span>Guide prices · availability on request</span></div>${cards()}<div id="no-results" class="empty-state" hidden><h2>A different adventure, perhaps?</h2><p>No journeys match those filters. Try another region or clear your search.</p><button class="button" id="clear-search" type="button">Show all journeys</button></div>${pricingNote}<noscript><p class="notice">Filters need JavaScript. All journey links and prices remain available.</p></noscript></div></section>${cta}`);
page('destinations.html','Three regions to explore','Kashmir, Ladakh, and Jammu destination ideas and journey proposals.',`${head('Destinations','Three places.<br>Endless perspective.','From quiet valleys and lake life to high mountains and forest-framed hills.')}<section class="section"><div class="wrap">${regionCards()}</div></section><section class="section"><div class="wrap style-grid"><div><span class="eyebrow">How do you like to travel?</span><h2>One north.<br>Many possibilities.</h2><p class="muted">Bring your own group, meet new people, or shape a journey around something you love.</p></div><div class="style-links">${[['Group','Shared journeys','Meet people who love the same kind of travel.'],['Women-only','Women, travelling together','A proposed format with support details agreed first.'],['Trek','Out on the trail','Walking-focused proposals with specialist support.'],['Private','Your people. Your pace.','Family time, couple getaways, and flexible routes.'],['Motorcycle','The road is part of the story','Riding proposals for experienced, licensed riders.'],['Pilgrimage','Time for what matters','Katra with a thoughtful hill-country extension.']].map(([type,title,text])=>`<a href="packages.html?type=${encodeURIComponent(type)}">${img(stylePhotos[type])}<span><strong>${title}</strong><small>${text}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div></div></section>${cta}`);
for(const r of regions)page(`${r.slug}.html`,`${r.name} journeys`,`${r.name} travel inspiration, itinerary proposals, and guide prices.`,`${head(r.name,r.line,r.description)}<div class="wrap destination-banner">${img(r.image,'',true)}<span>${r.name} · Destination inspiration</span></div><section class="section"><div class="wrap split"><div><span class="eyebrow">Follow your curiosity</span><h2>Stay a little longer.<br>See a little differently.</h2></div><div><ul class="tick-list">${r.highlights.map(h=>`<li>${h}</li>`).join('')}</ul><p class="muted">${r.note}</p></div></div></section><section class="section tint"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Your ${r.name} chapter</span><h2>Let the journey begin.</h2></div>${button(`packages.html?region=${r.name}`,'Search these journeys','outline')}</div>${cards(trips.filter(t=>t.region.includes(r.name)))}${pricingNote}</div></section>${cta}`);
function enquiryForm(id='enquiry',trip=null){return `<form class="enquiry-form" id="${id}" data-enquiry><div class="form-grid"><div class="field"><label for="${id}-name">Your name *</label><input id="${id}-name" name="name" autocomplete="name" required maxlength="100"></div><div class="field"><label for="${id}-phone">Phone number *</label><input id="${id}-phone" name="phone" type="tel" autocomplete="tel" required minlength="7" maxlength="30"></div><div class="field"><label for="${id}-email">Email address *</label><input id="${id}-email" name="email" type="email" autocomplete="email" required maxlength="180"></div><div class="field"><label for="${id}-travellers">Travellers *</label><input id="${id}-travellers" name="travellers" type="number" min="1" max="100" step="1" value="2" required></div><div class="field"><label for="${id}-destination">Destination *</label><select id="${id}-destination" name="destination" required><option value="">Please choose</option>${regions.map(r=>`<option ${trip?.region===r.name?'selected':''}>${r.name}</option>`).join('')}<option ${trip?.region==='Kashmir & Ladakh'?'selected':''}>Combined journey</option></select></div><div class="field"><label for="${id}-date">Preferred start date</label><input id="${id}-date" name="date" type="date"></div><div class="field full"><label for="${id}-trip">Journey</label><select id="${id}-trip" name="trip"><option value="custom">A custom journey</option>${trips.map(t=>`<option value="${t.slug}" ${trip?.slug===t.slug?'selected':''}>${t.name}</option>`).join('')}</select></div><div class="field full"><label for="${id}-budget">Land budget per person — optional</label><select id="${id}-budget" name="budget"><option value="">Prefer to discuss</option><option>Under ₹15,000</option><option>₹15,000–₹30,000</option><option>₹30,000–₹50,000</option><option>₹50,000+</option></select><p class="small muted">Your target budget, excluding travel to the starting point; this is not a package price.</p></div><div class="field"><label for="${id}-comfort">Stay preference — optional</label><select id="${id}-comfort" name="comfort"><option value="">Help me choose</option><option>Practical standard room</option><option>Comfort upgrade</option><option>Named boutique or heritage stay enquiry</option></select></div><div class="field"><label for="${id}-pace">Your preferred pace — optional</label><select id="${id}-pace" name="pace"><option value="">Flexible / discuss</option><option>Slower days and fewer hotel changes</option><option>A balance of sights and rest</option><option>More active days, with effort agreed</option></select></div><div class="field full"><label for="${id}-notes">What would make this trip special?</label><textarea id="${id}-notes" name="notes" maxlength="2000" placeholder="Your interests, extra nights, food preferences or walking requirements. Please avoid sending private documents here."></textarea></div></div><label class="consent"><input name="consent" type="checkbox" required><span>I have read the <a href="privacy.html">privacy notice</a> and want to prepare this trip enquiry. Dates and prices require confirmation. *</span></label><p class="small muted">This form prepares your message locally. Nothing is sent until you send it in WhatsApp or your email app.</p><button class="button" type="submit">Review my enquiry →</button><noscript><p>JavaScript is needed to prepare this message. <a href="${wa}">Contact us on WhatsApp</a> or <a href="mailto:${config.email}">email the team</a>.</p></noscript><section class="enquiry-result" hidden tabindex="-1" aria-label="Review your enquiry"><span class="eyebrow">Review & send</span><h3>Your journey starts here.</h3><p>Review your request below. <strong>It has not been sent.</strong></p><pre class="enquiry-summary"></pre><div class="actions"><a class="button send-whatsapp" href="${wa}">Open WhatsApp ↗</a><a class="button outline send-email" href="mailto:${config.email}">Open email draft ↗</a><button type="button" class="text-button copy-enquiry">Copy enquiry</button><button type="button" class="text-button edit-enquiry">Edit details</button></div><p class="copy-status small" role="status"></p></section></form>`;}
for(const t of trips)page(`${t.slug}.html`,`${t.name} — ${t.days} days`,`${t.days}-day ${t.region} itinerary proposal. ${t.price?`Guide ${money(t.price)} per person`:'Price on request'}. Explore the route and request your dates.`,`${tripPresentation(t,{esc,img,price,wa}).hero}${tripPresentation(t,{esc,img,price,wa}).planner}<div class="wrap"><div class="trip-facts"><div><small>The journey</small><strong>${t.days} days / ${t.nights} nights</strong></div><div><small>Starting point</small><strong>${t.start}</strong></div><div><small>Travel style</small><strong>${t.type}</strong></div><div><small>Pace</small><strong>${t.difficulty}</strong></div></div><nav class="section-nav" aria-label="Trip sections"><a href="#overview">Overview</a><a href="#itinerary">Itinerary</a><a href="#inclusions">Inclusions</a><a href="#dates">Dates & price</a><a href="#stays">Stays</a><a href="#package-details">Package details</a><a href="#packing">Packing</a><a href="#trip-faq">FAQs</a></nav></div><section class="section"><div class="wrap trip-layout"><div><section id="overview" class="trip-section"><span class="eyebrow">A closer look</span><h2>${t.days} days.<br>Room for your own story.</h2><p>${t.description} This proposal is a starting point: routing and services are confirmed in writing around your dates.</p>${tripPresentation(t,{esc,img,price,wa}).profile}<div class="route-line"><small>The route</small><p>${t.route}</p></div><div class="highlight-grid">${t.highlights.map((h,i)=>`<div><span>0${i+1}</span><h3>${h}</h3></div>`).join('')}</div><p class="small muted">${t.group} · ${t.season}. No departure, staffing, accommodation, or seat count is confirmed on this page.</p></section><section id="itinerary" class="trip-section"><span class="eyebrow">Your journey, day by day</span><h2>A route to look forward to.</h2><div class="route-overview">${t.itinerary.map((d,i)=>`<a href="#day-${i+1}"><span>DAY ${String(i+1).padStart(2,'0')}</span><strong>${esc(d.place)}</strong><small>${esc(d.title)}</small></a>`).join('')}</div><div class="expand-row"><button type="button" class="text-button expand-days">Expand all days</button></div>${t.itinerary.map((d,i)=>`<details class="itinerary-day" id="day-${i+1}" ${i===0?'open':''}><summary><span class="day-number">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(d.title)}</strong><small>${esc(d.place)}</small></span><span class="plus" aria-hidden="true">+</span></summary><div class="day-content">${dayPlanning(d,esc)}<p>${esc(d.description)}</p>${d.places?`<div class="day-places"><h4>Places to discover</h4><ul>${d.places.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div>`:''}${d.experiences?`<div class="day-experiences"><h4>Experiences to request</h4><ul>${d.experiences.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div>`:''}<div class="day-meta"><span><small>Proposed overnight</small>${esc(d.stay)}</span><span><small>Proposed meals</small>${esc(d.meals)}</span></div></div></details>`).join('')}</section><section id="inclusions" class="trip-section"><span class="eyebrow">Know the details</span><h2>What’s in the plan.</h2><p class="muted">Proposed inclusions need supplier confirmation. Only your accepted written quote determines the actual package.</p><div class="inclusion-grid"><div><h3>Proposed inclusions</h3><ul class="tick-list">${t.inclusions.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div><div><h3>Not assumed included</h3><ul class="cross-list">${t.exclusions.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div></div><p class="notice">“All-inclusive” does not mean every possible expense. Meals, transport, permits, activities, taxes, and supplements will be itemised in your final quote.</p></section><section id="dates" class="trip-section"><span class="eyebrow">Make room in your calendar</span><h2>Choose your preferred dates.</h2><div class="date-request"><div><span class="price-label">Planning guide</span><div class="inline-price">${price(t)}</div><p class="small muted">${t.quoteReason||""}</p><p class="small muted">${t.price?t.priceBasis:'A tailored supplier quote will confirm the rate and services.'}</p></div><div><p>These proposed dates are planning suggestions; departures and seats still require confirmation.</p><a href="#trip-enquiry" data-open-planner>Request availability for your dates ↗</a></div></div>${pricingNote}${t.region==='Ladakh'?'<p class="small muted">This proposal allows extra arrival time and differs in duration from some price benchmarks. It is not a like-for-like confirmed offer.</p>':''}${packageDetails(t,{esc,img}).dates}</section>${packageDetails(t,{esc,img}).stays}${packageDetails(t,{esc,img}).practical}${journeyExtensions(t,{esc,wa})}<section id="packing" class="trip-section"><span class="eyebrow">A little preparation</span><h2>Pack for possibilities.</h2><div class="packing-grid"><div><h3>Everyday essentials</h3><ul><li>Valid ID and confirmed travel documents</li><li>Day bag and reusable water bottle</li><li>Charger, power bank, and offline contacts</li></ul></div><div><h3>For the landscape</h3><ul><li>Layers suited to your travel dates</li><li>Comfortable shoes with good grip</li><li>Sun and rain protection</li></ul></div></div><p class="small muted">${t.trek?'Agree a specialist equipment, fitness, support, and evacuation plan with the trek operator. ':t.riding?'Confirm required riding gear, licence eligibility, rental liability, and support before paying. ':''}Request a date-specific checklist. Seek individual professional advice where altitude or exertion is involved.</p></section><section class="trip-section"><span class="eyebrow">Destination inspiration</span><h2>A glimpse of what’s out there.</h2>${gallery([...new Set((t.gallery?.length?t.gallery:[...(t.slug==='kashmir-heritage-stay'?['jamia','pashmina-loom']:t.region==='Jammu'?['sanasar','bhaderwah','katra','patnitop']:t.region==='Ladakh'?['zanskar-road','alchi','nubra','pangong','khardung']:['aru','verinag','kokernag','gurez-village','dal','gulmarg'])]))].filter(key=>key!==t.image&&!trips.filter(x=>x.slug!==t.slug&&x.region===t.region).slice(0,3).some(x=>x.image===key)).slice(0,3))}</section>${reviewsBlock()}<section class="trip-section"><span class="eyebrow">Plan with care</span><h2>Your comfort & support.</h2><div class="highlight-grid"><div><span>01</span><h3>Route & access</h3><p class="small muted">Confirm current roads, permissions, and suitable alternatives before departure.</p></div><div><span>02</span><h3>Named support</h3><p class="small muted">Ask for your trip coordinator, guide arrangements, and emergency contacts in writing.</p></div><div><span>03</span><h3>Your pace</h3><p class="small muted">Discuss altitude, activity levels, rest time, and your group’s needs before committing.</p></div></div></section><section id="trip-faq" class="trip-section"><span class="eyebrow">Before you decide</span><h2>Your questions, answered.</h2>${faqList([faqs[1],faqs[2],faqs[4],faqs[6]])}</section><section id="trip-enquiry" class="trip-section"><span class="eyebrow">Tell us your plans</span><h2>Make this journey yours.</h2>${enquiryForm('trip-enquiry-form',t)}</section></div><aside class="booking-card"><span class="eyebrow">Your ${t.region} chapter</span><h2>${t.name}</h2><p>${t.days} days · ${t.nights} nights</p><div class="booking-price">${price(t)}</div><p class="small muted">${config.pricingNote}</p>${sidebarDates(t,esc)}<label for="preferred-date">Your preferred start date</label><input id="preferred-date" type="date" data-preferred-date><a class="button request-date" href="#trip-enquiry">Request availability ↗</a><a class="text-link" href="${wa}?text=${encodeURIComponent('Hello The Holiday Host, I would like to discuss '+t.name+'.')}">Talk on WhatsApp ↗</a><div class="booking-note">✓ No payment collected here.<br>Written confirmation comes first.</div><a href="departures.html">More about departure dates</a></aside></div></section><section class="section tint"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Keep exploring</span><h2>Another way to go.</h2></div><a href="packages.html">All journeys ↗</a></div>${cards(trips.filter(x=>x.slug!==t.slug&&x.region===t.region).slice(0,3))}</div></section><div class="mobile-booking"><span>${t.price?`${money(t.price)} <small>guide / person</small>`:'Quote on request'}</span><a class="button" href="#trip-enquiry">Enquire ↗</a></div>`);
page('departures.html','Request your travel dates','Request a travel date for Kashmir, Ladakh, or Jammu. Confirmed departures and seats are not yet available.',`${head('Travel dates','Put a little adventure<br>in your calendar.','Tell us when you’d like to travel. We’ll discuss a suitable group departure or private itinerary, subject to confirmation.')}<section class="section"><div class="wrap"><div class="departure-panel"><div><span class="eyebrow">Honest availability</span><h2>Your dates.<br>Our starting point.</h2><p>Explore suggested seasonal starts below, or choose your own date. These are sample planning dates, not confirmed departures or event schedules.</p></div><form id="date-planner" class="date-planner" action="contact.html"><div class="field"><label for="departure-region">Destination</label><select id="departure-region" name="region">${regions.map(r=>`<option>${r.name}</option>`).join('')}</select></div><div class="field"><label for="departure-date">Preferred departure *</label><input id="departure-date" name="date" type="date" required></div><button class="button" type="submit">Request these dates ↗</button></form></div>${planningCalendar(trips,{esc})}<div class="section-head space-top"><div><span class="eyebrow">Find a starting point</span><h2>Which journey calls?</h2></div></div>${cards(trips.filter(t=>t.type==='Group').slice(0,6))}${pricingNote}</div></section>${cta}`);
page('contact.html','Plan your Kashmir, Ladakh or Jammu trip','Prepare a custom trip enquiry and send it to The Holiday Host on WhatsApp or email.',`${head('Plan your journey','Good journeys begin<br>with a hello.','A destination in mind, or just a feeling? Tell us what matters to you and we’ll start there.')}<section class="section"><div class="wrap contact-layout"><div><span class="eyebrow">Your travel wish list</span><h2>Let’s shape the details.</h2>${enquiryForm()}</div><aside class="contact-card"><span class="eyebrow">Prefer a conversation?</span><h2>We’re here<br>to talk travel.</h2><a class="contact-big" href="tel:${config.phone}">+91 99062 69900</a><a href="mailto:${config.email}">${config.email}</a>${button(wa,'Open WhatsApp')}<hr><h3>Based in Srinagar</h3><p>${esc(config.location)}<br>Opening hours to be confirmed.</p><p class="small muted">Phone and WhatsApp supplied by the owner. Email carried over from the existing website.</p><p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(config.location)}">Open address in Google Maps ↗</a></p><a href="faq.html">Read the FAQs ↗</a></aside></div></section>`);
page('about.html','The story behind The Holiday Host','Get to know The Holiday Host and our proposed Kashmir, Ladakh, and Jammu journeys.',`${head('Our story','Good places.<br>Good company.<br>A little more time.','Begin planning a journey through Kashmir, Ladakh, and Jammu—around the things that matter to you.')}<section class="section"><div class="wrap split"><div class="editorial-photo">${img('dal-lake')}</div><div><span class="eyebrow">A more personal way north</span><h2>Start with a place.<br>Make it your story.</h2><p>Perhaps you want a different side of Kashmir. Perhaps it’s the Ladakh road you keep thinking about. Or time in Jammu’s hill country with your people.</p><p>Explore the proposals, ask your questions, and request the details in writing. A good trip should feel clear before it feels close.</p><div class="notice">Our owner introduction, team profiles, and approved founder video are coming soon. Business registration and accreditation details will appear only after evidence is supplied.</div></div></div></section><section class="section tint"><div class="wrap"><span class="eyebrow">Before you make it official</span><h2>Trust begins with the details.</h2><div class="info-grid">${[['A written proposal','Named stays, route transport, meals, and the exact services you’re paying for.'],['Clear booking terms','Payment, cancellation, refund, and disruption arrangements agreed before payment.'],['Real people, real stories','Guest feedback and team credentials appear only when verified and approved.']].map(([h,p],i)=>`<article><span>0${i+1}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>${cta}`);
const guides=[{slug:'choosing-your-region',tag:'Where to begin',title:'Kashmir, Ladakh, or Jammu?',intro:'Three regions. Three different starting points.',image:'pangong',body:'<h2>Follow the pace you want</h2><p>Kashmir offers lake life and valley stays. Ladakh calls for deliberate planning around altitude, driving, and permissions. Jammu offers hill-country stays and a Katra base option.</p><h2>Compare the journey, not just the number</h2><p>Look at nights, sharing, transport, meals, and optional costs. A lower headline price does not automatically mean the same services. Ask for an itemised proposal.</p>'},{slug:'understanding-trip-prices',tag:'Plan with clarity',title:'What a trip price really includes',intro:'The small print should be easy to understand.',image:'dal-lake',body:'<h2>Start with the basis</h2><p>Guide prices are planning estimates per person on proposed shared occupancy, not confirmed offers. Check the room type, group size, dates, vehicle, and taxes.</p><h2>Check the everyday costs</h2><p>Breakfast and dinner feature in overnight proposals. Lunch, flights, insurance, extra nights, and optional activities are usually separate unless expressly included. Ask about permits, local transport, and tickets.</p><h2>Keep the final version</h2><p>Your accepted quote should list the total, inclusions, exclusions, supplements, payment schedule, and cancellation terms.</p>'},{slug:'planning-a-mountain-journey',tag:'Travel thoughtfully',title:'Leave room for the mountains',intro:'An adaptable plan is part of the experience.',image:'patnitop',body:'<h2>Think beyond a checklist</h2><p>Roads, weather, permissions, and local restrictions can change the plan. Discuss alternatives and leave contingency time around onward travel.</p><h2>Choose a pace that works</h2><p>More places can mean more driving and hotel changes. Ask whether fewer bases, extra rest days, or a private route suit your group better.</p><h2>Prepare for your own needs</h2><p>Request a date-specific packing list. Discuss accessibility and dietary arrangements directly. Seek professional advice about altitude or exertion where relevant; a sample itinerary cannot assess individual suitability.</p>'}];
guides.unshift(...heritageGuides);
