for(const g of guides)page(`${g.slug}.html`,g.title,g.intro,`${head(g.tag,g.title,g.intro)}<section class="section"><div class="wrap prose"><figure>${img(g.image)}</figure>${g.body}<p><a href="blog.html">← More field notes</a></p></div></section>${cta}`);
